22	export function initDatabaseMetrics(knex: Knex) {
23	  const seenProm = new Set<string>();
24	  const seen = new Set<string>();
25	  const meter = metrics.getMeter('default');
26	  return {
27	    entities_count_prom: createGaugeMetric({
28	      name: 'catalog_entities_count',
29	      help: 'Total amount of entities in the catalog. DEPRECATED: Please use opentelemetry metrics instead.',
30	      labelNames: ['kind'],
31	      async collect() {
32	        const results = await knex<DbSearchRow>('search')
33	          .where('key', '=', 'kind')
34	          .whereNotNull('value')
35	          .select({ kind: 'value', count: knex.raw('count(*)') })
36	          .groupBy('value');
37	
38	        results.forEach(({ kind, count }) => {
39	          seenProm.add(kind);
40	          this.set({ kind }, Number(count));
41	        });
42	
43	        // Set all the entities that were not seenProm to 0 and delete them from the seenProm set.
44	        seenProm.forEach(kind => {
45	          if (!results.some(r => r.kind === kind)) {
46	            this.set({ kind }, 0);
47	            seenProm.delete(kind);
48	          }
49	        });
50	      },
51	    }),
52	    registered_locations_prom: createGaugeMetric({
53	      name: 'catalog_registered_locations_count',
54	      help: 'Total amount of registered locations in the catalog. DEPRECATED: Please use opentelemetry metrics instead.',
55	      async collect() {
56	        const total = await knex<DbLocationsRow>('locations').count({
57	          count: '*',
58	        });
59	        this.set(Number(total[0].count));
60	      },
61	    }),
62	    relations_prom: createGaugeMetric({
63	      name: 'catalog_relations_count',
64	      help: 'Total amount of relations between entities. DEPRECATED: Please use opentelemetry metrics instead.',
65	      async collect() {
66	        const total = await knex<DbRelationsRow>('relations').count({
67	          count: '*',
68	        });
69	        this.set(Number(total[0].count));
70	      },
71	    }),
72	    entities_count: meter
73	      .createObservableGauge('catalog_entities_count', {
74	        description: 'Total amount of entities in the catalog',
75	      })
76	      .addCallback(async gauge => {
77	        const results = await knex<DbSearchRow>('search')
78	          .where('key', '=', 'kind')
79	          .whereNotNull('value')
80	          .select({ kind: 'value', count: knex.raw('count(*)') })
81	          .groupBy('value');
82	
83	        results.forEach(({ kind, count }) => {
84	          seen.add(kind);
85	          gauge.observe(Number(count), { kind });
86	        });
87	
88	        // Set all the entities that were not seen to 0 and delete them from the seen set.
89	        seen.forEach(kind => {
90	          if (!results.some(r => r.kind === kind)) {
91	            gauge.observe(0, { kind });
92	            seen.delete(kind);
93	          }
94	        });
95	      }),
96	    registered_locations: meter
97	      .createObservableGauge('catalog_registered_locations_count', {
98	        description: 'Total amount of registered locations in the catalog',
99	      })
100	      .addCallback(async gauge => {
101	        if (knex.client.config.client === 'pg') {
102	          // https://stackoverflow.com/questions/7943233/fast-way-to-discover-the-row-count-of-a-table-in-postgresql
103	          const total = await knex.raw(`
104	            SELECT reltuples::bigint AS estimate
105	            FROM   pg_class
106	            WHERE  oid = 'locations'::regclass;
107	          `);
108	          gauge.observe(Number(total.rows[0].estimate));
109	        } else {
110	          const total = await knex<DbLocationsRow>('locations').count({
111	            count: '*',
112	          });
113	          gauge.observe(Number(total[0].count));
114	        }
115	      }),
116	    relations: meter
117	      .createObservableGauge('catalog_relations_count', {
118	        description: 'Total amount of relations between entities',
119	      })
120	      .addCallback(async gauge => {
121	        if (knex.client.config.client === 'pg') {
122	          // https://stackoverflow.com/questions/7943233/fast-way-to-discover-the-row-count-of-a-table-in-postgresql
123	          const total = await knex.raw(`
124	            SELECT reltuples::bigint AS estimate
125	            FROM   pg_class
126	            WHERE  oid = 'relations'::regclass;
127	          `);
128	          gauge.observe(Number(total.rows[0].estimate));
129	        } else {
130	          const total = await knex<DbRelationsRow>('relations').count({
131	            count: '*',
132	          });
133	          gauge.observe(Number(total[0].count));
134	        }
135	      }),
136	  };
137	}
